class Solution:
    def arrayPairSum(self, nums: list[int]) -> int:
        counts = [0] * 20001
        for value in nums:
            counts[value + 10000] += 1
        take = True
        total = 0
        for index, count in enumerate(counts):
            selected = (count + int(take)) // 2
            total += selected * (index - 10000)
            if count % 2:
                take = not take
        return total
